package org.novasos.healthysv2.pharmacy;
import static org.assertj.core.api.Assertions.*;import java.math.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.novasos.healthysv2.TestcontainersConfiguration;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.Import;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;
@ActiveProfiles("test")@SpringBootTest@Import(TestcontainersConfiguration.class)@Transactional class PharmacyRepositoryIntegrationTests{
 @Autowired PrescriptionRepository prescriptions;@Autowired MedicationStockRepository stocks;@Autowired JdbcTemplate jdbc;
 @Test void persistsPrescriptionDispenseAndStock(){Graph g=graph();var stock=stocks.saveAndFlush(MedicationStock.create(g.organization,g.medication,"LOT-DB",new BigDecimal("20"),LocalDate.now().plusYears(1)));var p=Prescription.create(g.patient,null,g.doctor,g.organization,Instant.now().plus(Duration.ofDays(30)));p.addItem(g.medication,"500 mg","BID","ORAL","5 days",new BigDecimal("10"),null);var saved=prescriptions.saveAndFlush(p);var item=saved.getItems().getFirst();saved.dispense(g.organization,g.pharmacist,List.of(new Prescription.DispenseLine(item.getId(),new BigDecimal("10"),"LOT-DB")));stock.consume(new BigDecimal("10"));saved=prescriptions.saveAndFlush(saved);stocks.flush();var found=prescriptions.findById(saved.getId()).orElseThrow();assertThat(found.getItems()).hasSize(1);assertThat(found.getDispenses()).singleElement().satisfies(d->assertThat(d.getItems()).hasSize(1));assertThat(stocks.findById(stock.getId()).orElseThrow().getQuantity()).isEqualByComparingTo("10");}
 private Graph graph(){UUID patientPerson=person(),doctorPerson=person(),pharmacistPerson=person(),patient=UUID.randomUUID(),doctor=professional(doctorPerson,"DOCTOR"),pharmacist=professional(pharmacistPerson,"PHARMACIST"),organization=UUID.randomUUID(),medication=UUID.randomUUID();jdbc.update("insert into patient.patient(id,person_id,patient_number) values (?,?,?)",patient,patientPerson,"PAT-"+patient);jdbc.update("insert into organization.organization(id,organization_number,name) values (?,?,?)",organization,"ORG-"+organization,"Pharmacy");jdbc.update("insert into catalog.medication_catalog(id,code,name,active) values (?,?,?,?)",medication,"MED-"+medication.toString().substring(0,4),"Medicine",true);return new Graph(patient,doctor,pharmacist,organization,medication);}private UUID person(){UUID id=UUID.randomUUID();jdbc.update("insert into identity.person(id,person_number,first_name,last_name,status) values (?,?,?,?,?)",id,"PER-"+id,"Test","User","ACTIVE");return id;}private UUID professional(UUID person,String type){UUID id=UUID.randomUUID();jdbc.update("insert into professional.professional(id,person_id,professional_number,professional_type,status) values (?,?,?,?,?)",id,person,"PRO-"+id,type,"ACTIVE");return id;}record Graph(UUID patient,UUID doctor,UUID pharmacist,UUID organization,UUID medication){}
}
